-- 주문: A-ORD-010 조회 권한 + 거점 범위(BR-102)
CREATE OR REPLACE FUNCTION public.can_read_order(p_order bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT public.has_permission('A-ORD-010', 'READ') AND EXISTS (
    SELECT 1 FROM service_order o WHERE o.id = p_order AND public.can_access_branch(o.branch_id)
  )
$$;
--> statement-breakpoint
CREATE POLICY order_select ON public.service_order FOR SELECT TO authenticated
  USING (public.has_permission('A-ORD-010', 'READ') AND public.can_access_branch(branch_id));
--> statement-breakpoint
CREATE POLICY order_item_select ON public.order_item FOR SELECT TO authenticated USING (public.can_read_order(order_id));
--> statement-breakpoint
CREATE POLICY order_history_select ON public.order_status_history FOR SELECT TO authenticated USING (public.can_read_order(order_id));
--> statement-breakpoint
CREATE POLICY order_change_select ON public.order_change_request FOR SELECT TO authenticated USING (public.can_read_order(order_id));
--> statement-breakpoint
CREATE POLICY payment_select ON public.payment FOR SELECT TO authenticated USING (public.can_read_order(order_id));
--> statement-breakpoint
CREATE POLICY refund_select ON public.refund FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM payment p WHERE p.id = payment_id AND public.can_read_order(p.order_id)));
--> statement-breakpoint
-- 고객: 주문을 볼 수 있는 관리자 중 그 고객의 주문이 자기 거점 범위에 있을 때만 (고객 화면 A-CUS 는 단계 3)
CREATE POLICY customer_select ON public.customer FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM service_order o WHERE o.customer_id = customer.id AND public.can_read_order(o.id)));
