-- 근무표: A-DSP-040 + 기사 소속 거점 범위
CREATE OR REPLACE FUNCTION public.can_access_technician(p_tech bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM technician t WHERE t.id = p_tech AND public.can_access_branch(t.branch_id))
$$;
--> statement-breakpoint
